package com.careerbridge.model;
import jakarta.persistence.*;
@Entity @Table(name="resources") public class Resource { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(optional=false) @JoinColumn(name="skill_id") private Skill skill; @Column(nullable=false) private String title; @Column(nullable=false) private String type; private String url; private String level; public Resource(){} public Resource(Skill skill,String title,String type,String url,String level){this.skill=skill;this.title=title;this.type=type;this.url=url;this.level=level;} public Long getId(){return id;} public Skill getSkill(){return skill;} public String getTitle(){return title;} public String getType(){return type;} public String getUrl(){return url;} public String getLevel(){return level;} }
